44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	
56	const sumBasePremiums = (items: Item[]): number =>
57	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
58	
59	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
60	// rounded, intermediate amounts stay fractional.
61	const roundInMHPCOsFavour = Math.ceil;
62	
63	const quotePremium = (items: Item[]): number => {
64	  const basePremium = sumBasePremiums(items);
65	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
66	  return roundInMHPCOsFavour(
67	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
68	  );
69	};
70	
71	export const runScenario = (scenario: Scenario): ScenarioResults => ({
72	  results: scenario.steps.map((step) => ({
73	    premium: quotePremium((step as QuoteStep).items),
74	  })),
75	});
