const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

export type InsurableItemType = keyof typeof BASE_PREMIUMS;

const basePremiumFor = (item: Item): number =>
  BASE_PREMIUMS[item.type as InsurableItemType];

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumFor(item), 0);
